cat > /tmp/test_api_response.py << 'EOF'
#!/usr/bin/env python3
import json
import requests

# API 配置
api_key = "sk-30hw0QuR0UD2t6ub808670A2Da6641159aDbAe54519f6743"
api_url = "https://api.apiyi.com/v1beta/models/gemini-3-pro-image-preview:generateContent"

# 简单的 prompt
payload = {
    "contents": [{
        "parts": [{
            "text": "请生成一张超薄丝袜的产品照片。商业产品摄影风格，白色背景，一双半透明超薄丝袜优雅摆放，展示轻薄质感。高质量，光线柔和。"
        }]
    }],
    "generationConfig": {
        "responseModalities": ["IMAGE"],
        "imageConfig": {
            "aspectRatio": "1:1",
            "imageSize": "2K"
        }
    }
}

headers = {
    "Content-Type": "application/json",
    "Authorization": f"Bearer {api_key}"
}

print("发送请求...")
response = requests.post(api_url, headers=headers, json=payload, timeout=180)

print(f"状态码: {response.status_code}")
print(f"\n响应头:")
for k, v in response.headers.items():
    print(f"  {k}: {v}")

# 解析响应
try:
    data = response.json()
    print(f"\n响应结构:")
    print(json.dumps(data, indent=2, ensure_ascii=False)[:2000])

    # 查找图片数据
    if "candidates" in data:
        print(f"\n找到 candidates，数量: {len(data['candidates'])}")
        for i, candidate in enumerate(data["candidates"]):
            print(f"\nCandidate {i}:")
            content = candidate.get("content", {})
            parts = content.get("parts", [])
            print(f"  Parts 数量: {len(parts)}")

            for j, part in enumerate(parts):
                print(f"  Part {j} keys: {list(part.keys())}")

                if "inlineData" in part:
                    inline_data = part["inlineData"]
                    print(f"    找到 inlineData!")
                    print(f"    mimeType: {inline_data.get('mimeType')}")
                    img_data = inline_data.get("data", "")
                    print(f"    data 长度: {len(img_data)}")

                    # 保存图片
                    import base64
                    img_bytes = base64.b64decode(img_data)
                    filename = f"/tmp/stockings_{i}_{j}.png"
                    with open(filename, "wb") as f:
                        f.write(img_bytes)
                    print(f"    已保存到: {filename}")
                elif "text" in part:
                    text = part["text"]
                    print(f"    文本内容 (前100字符): {text[:100]}")

    else:
        print("\n未找到 candidates")
        print(f"响应的顶层 keys: {list(data.keys())}")

except Exception as e:
    print(f"\n解析错误: {e}")
    import traceback
    traceback.print_exc()

EOF
